import java.time.*;
import java.util.*;

class GreetingService {
    private final Clock clock;
    private final ZoneId zone;

    GreetingService(Clock c, ZoneId z) {
        clock = c;
        zone = z;
    }

    String greeting() {
        int h = Instant.now(clock).atZone(zone).getHour();
        return h >= 5 && h < 12 ? "morning" : h < 18 && h >= 12 ? "afternoon" : "night";
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Instant now = Instant.parse(sc.next());
        ZoneId zone = ZoneId.of(sc.next());
        System.out.println(new GreetingService(Clock.fixed(now, ZoneOffset.UTC), zone).greeting());
    }
}

